import Foundation

/// Literal input/expected pairs transcribed from the user's Sample Recipe Data.txt.
/// Only SAMPLE/this/Should be framing and outer blank separator rows are removed.
/// Expected files are independent user examples, never generated by the transform.
enum UserRecipeFixtures {
    static let directory=TestPaths.fixtures
    static func pair(_ number:Int)throws->(String,String) {
        (try String(contentsOf:directory.appendingPathComponent("recipe-user-sample\(number)-input.txt"),encoding:.utf8),
         try String(contentsOf:directory.appendingPathComponent("recipe-user-sample\(number)-expected.txt"),encoding:.utf8))
    }
    /// An explicit user-configurable recipe for these supplied examples. This
    /// deliberately promises no inference about arbitrary headings or notes.
    static var configured:AutomationDefinition {
        var value=AutomationDefinition.example
        value.name="My ingredient cleanup"
        value.steps=AutomationDefinition.shoppingRecipeSteps
        return value
    }
}

@main struct UserRecipeChecks {
    static func main() {
        Checks.run("UserRecipeChecks") {
        let definition=UserRecipeFixtures.configured
        try definition.validate()
        for (index,rows) in [32,7,13,13].enumerated() {
            let number=index+1,(input,expected)=try UserRecipeFixtures.pair(number)
            fixtureCheck(expected.split(separator:"\n").count==rows,"sample \(number) independently supplied expected \(rows) ingredient rows")
            let output=try definition.transform(input)
            check(output.utf8.elementsEqual(expected.utf8),"sample \(number) exact user expected bytes")
            check(try definition.transform(output).utf8.elementsEqual(expected.utf8),"sample \(number) cleanup idempotent")
            var renamed=definition;renamed.name="Scott's chosen label"
            check(try renamed.transform(input).utf8.elementsEqual(expected.utf8),"sample \(number) configurable name does not affect behavior")
        }
        for (inputName,expectedName,isPlain) in [
            ("recipe-markdown-input.txt","recipe-cleaned-expected.txt",false),
            ("recipe-browser-plain-input.txt","recipe-browser-cleaned-expected.txt",false),
            ("recipe-plain-copy-derived.txt","recipe-cleaned-expected.txt",true)
        ] {
            let input=try String(contentsOf:UserRecipeFixtures.directory.appendingPathComponent(inputName),encoding:.utf8)
            var expected=try String(contentsOf:UserRecipeFixtures.directory.appendingPathComponent(expectedName),encoding:.utf8)
            // The historical Markdown source has a literal final quote; its derived
            // plain-copy fixture omits that quote, as the existing regression records.
            if isPlain { expected=expected.replacingOccurrences(of:"chopped\"",with:"chopped") }
            check(try definition.transform(input).utf8.elementsEqual(expected.utf8),"prior confirmed cleanup exact compatibility: \(inputName)")
        }
        check(try definition.transform("Ingredients\nCups\nMetric\nGarnish (optional)\nSauce:\n2 eggs (optional)\n")=="2 eggs (optional)\n","configured structural headings removed without blanket parenthetical stripping")
        let (_,first)=try UserRecipeFixtures.pair(1)
        fixtureCheck(first.components(separatedBy:"1/2 teaspoon black pepper").count==3,"duplicate ingredient rows preserved")
        let (_,third)=try UserRecipeFixtures.pair(3)
        fixtureCheck(third.contains("½ teaspoon kosher salt") && third.contains("⅛ teaspoon ground nutmeg") && third.contains("won’t"),"Unicode fractions and punctuation unchanged")
        let (_,fourth)=try UserRecipeFixtures.pair(4)
        fixtureCheck(fourth.hasPrefix("2 large chicken breasts\n") && fourth.contains("2 tbps Dijon mustard"),"unmarked first ingredient retained and user's spelling preserved")
        check(definition.input == .document && definition.output == .editor && definition.previewBeforeApply == false,"cleanup remains direct current-document action")
        check(AutomationDefinition.remindersExample.output == .reminders && AutomationDefinition.remindersExample.id != definition.id,"Reminders remains separate explicit action")
        Checks.summary { "PASS UserRecipeChecks: \(Checks.count) assertions" }
        }
    }
}
